using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Sift.Api.Domain.Entities;

namespace Sift.Api.Data.Configurations;

public sealed class SteamAppConfiguration : IEntityTypeConfiguration<SteamApp>
{
    public void Configure(EntityTypeBuilder<SteamApp> builder)
    {
        builder.ToTable("steam_apps");
        builder.HasKey(a => a.AppId);

        // AppIds are assigned by Valve, never generated by us.
        builder.Property(a => a.AppId).ValueGeneratedNever();
        builder.Property(a => a.Name).HasMaxLength(256).IsRequired();
        builder.Property(a => a.IconHash).HasMaxLength(64);
    }
}
